import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';

  /** Validates input against the tool's inputSchema before execution; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = getValidator(tool);
    if (!validate(input)) {
      const rejection = formatRejection(name, validate.errors);
      log.warn('tool', 'input validation failed', {name, rejection});
      return {result: rejection};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function getValidator(tool: StoredTool): ValidateFunction {
  if (typeof tool.definitionSource !== 'function') {
    return tool.validateInput;
  }
  const resolved = tool.definitionSource();
  return compileSchema(resolved.name, resolved.inputSchema);
}

const ajv = new Ajv({allErrors: true, format: false});

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {
      cause: error,
    });
  }
}

function formatRejection(toolName: string, errors: ErrorObject[] | null | undefined): string {
  return `Invalid input for tool "${toolName}": ${ajv.errorsText(errors, {dataVar: 'input'})}`;
}

